import { expect } from "vitest";
import { outcomes } from "@shivaedev/test-story/server/outcomes.ts";
import { generatedOnce, generator, importsTheServerList, notesProject, registrationsProject } from "#test/generator.ts";

const LIST = "src/generated/server/modules.ts";
const HEADER =
	"// Generated by @shivaedev/build: the server's module list, every exported registration written `satisfies AppModule` in path order. Do not edit or commit this file; run `pnpm generate` to write it again.";

generator.it(
	"generate lists every exported registration written satisfies AppModule in its file's path order and leaves out a kit's",
	[registrationsProject()],
	function* ({ generatedFile, generates }) {
		yield* outcomes([
			["generate", () => generates(), { files: { [LIST]: "written" }, problems: [], programBuilt: false, result: "succeeded" }],
			[
				"the list",
				() => generatedFile(LIST),
				[
					HEADER,
					'import { archiveRegistration } from "#modules/archive/server/registration.ts";',
					'import { notesRegistration } from "#modules/notes/server/registration.ts";',
					'import { tagsRegistration } from "#modules/tags/server/registration.ts";',
					"",
					"export const modules = [",
					"\tarchiveRegistration,",
					"\tnotesRegistration,",
					"\ttagsRegistration,",
					"] as const;",
					"",
				].join("\n"),
			],
		]);
	},
);

generator.it(
	"generate writes an empty list for a project that imports it and has no registration yet",
	[notesProject(), importsTheServerList(), generatedOnce()],
	function* ({ generatedFile }) {
		expect(yield* generatedFile(LIST)).toBe(`${HEADER}\n\nexport const modules = [] as const;\n`);
	},
);

generator.it(
	"generate writes no list for a project that neither registers a module nor imports the list",
	[notesProject(), generatedOnce()],
	function* ({ generatedFile }) {
		expect(yield* generatedFile(LIST)).toBe("missing");
	},
);

generator.it(
	"after a module folder gains its registration, generate --check names the stale list and generate adds the module",
	[registrationsProject(), generatedOnce()],
	function* ({ addsRegistration, generatedFile, generates, generatesWithCheck }) {
		yield* addsRegistration("Labels");

		yield* outcomes([
			[
				"generate --check",
				() => generatesWithCheck(),
				{ files: { [LIST]: "stale" }, problems: [`${LIST} is stale; run \`pnpm generate\``], result: "failed" },
			],
			["generate", () => generates(), { files: { [LIST]: "written" }, problems: [], result: "succeeded" }],
			["the list", () => generatedFile(LIST), expect.stringContaining("\tarchiveRegistration,\n\tlabelsRegistration,\n\tnotesRegistration,\n")],
		]);
	},
);

for (const shape of ["through a separate export list", "typed through a namespace import"] as const) {
	generator.it(
		`generate lists a registration ${shape} under its exported name`,
		[registrationsProject(), generatedOnce()],
		function* ({ addsRegistration, generatedFile, generates }) {
			yield* addsRegistration("Labels", shape);

			yield* outcomes([
				["generate", () => generates(), { files: { [LIST]: "written" }, problems: [], result: "succeeded" }],
				[
					"the list",
					() => generatedFile(LIST),
					expect.stringContaining('import { labelsRegistration } from "#modules/labels/server/registration.ts";'),
				],
			]);
		},
	);
}

const NOT_SATISFIED =
	"labelsRegistration names what it serves and its services but is not written `satisfies AppModule`, so the server's module list leaves it out; write `satisfies AppModule` after its object, with AppModule imported from @shivaedev/server/AppModule.ts";

const REFUSALS = [
	[
		"typed : AppModule",
		"labelsRegistration is typed as AppModule, which leaves it out of the server's module list and loses its module's services; write `satisfies AppModule` after its object instead",
	],
	["with no annotation", NOT_SATISFIED],
	["in the group and handlers form with no annotation", NOT_SATISFIED],
	[
		"built by a function call",
		"exports no registration written `satisfies AppModule`, so the server's module list leaves its module out; export the registration as a const written `satisfies AppModule`, with AppModule imported from @shivaedev/server/AppModule.ts",
	],
] as const;

for (const [shape, refusal] of REFUSALS) {
	generator.it(
		`a registration ${shape} stops generate with a message naming its file and satisfies AppModule, and the list stays as it was`,
		[registrationsProject(), generatedOnce()],
		function* ({ addsRegistration, generatedFile, generates }) {
			const before = yield* generatedFile(LIST);

			yield* addsRegistration("Labels", shape);

			yield* outcomes([
				[
					"generate",
					() => generates(),
					{ files: { [LIST]: "refused" }, problems: [`src/modules/labels/server/registration.ts: ${refusal}`], result: "failed" },
				],
				["the list", () => generatedFile(LIST), before],
			]);
		},
	);
}
